# CSD_RATIONALE_BEGIN
# Use one decreasing decoding loop with explicit phases:
# "reason" for ordinary free-form reasoning, "seek_span" when the model appears
# ready to naturally open a << ... >> span, "inside_span" while a span is open,
# and "done" after a completed final span. In natural-delimiter mode, ordinary
# reasoning always uses AppendUnconstrainedStep. A span opens only when
# EndsWithLeftDelimiter(generated) becomes true after an unconstrained step.
# While inside a span, prefer the positive guard
# helpers.IsComplete(generated) or helpers.CanConstrain(generated), then consume
# AppendConstrainedStep. After each constrained step, first check for a
# right-delimiter close event, then allow bounded local recovery with a saved
# checkpoint if the span became dead. Final readiness is conservative: do not
# trigger from a tiny local threshold. Instead require either an explicit
# scratch-to-final transition signal via at least one prior closed span plus
# moderate additional reasoning, or a stronger parser signal near completion.
# After a non-final span closes, continue ordinary reasoning and later seek a
# subsequent verified span. Every loop branch either consumes one helper step or
# breaks.
# CSD_RATIONALE_END
phase = "reason"
closed_spans = 0
reasoning_steps = 0
post_span_reasoning = 0
final_ready = False
checkpoint = []
has_checkpoint = False

# invariant helpers.lm == lm
# invariant helpers.parser == parser
# invariant lm.ValidTokensIdsLogits()
# invariant 0 <= stepsLeft <= maxSteps
# invariant |generated| + stepsLeft <= maxSteps
# decreases stepsLeft
while stepsLeft > 0:
    if phase == "done":
        break

    if helpers.IsComplete(generated):
        break

    if phase == "inside_span":
        if helpers.IsComplete(generated) or helpers.CanConstrain(generated):
            generated, stepsLeft = helpers.AppendConstrainedStep(prompt, generated, stepsLeft)
            if helpers.EndsWithRightDelimiter(generated):
                closed_spans = closed_spans + 1
                has_checkpoint = False
                post_span_reasoning = 0
                if final_ready:
                    phase = "done"
                else:
                    phase = "reason"
            else:
                if has_checkpoint:
                    restored = helpers.RestoreIfDead(generated, checkpoint)
                    if restored != generated:
                        generated = restored
                        has_checkpoint = False
                        phase = "reason"
        else:
            if has_checkpoint:
                generated = helpers.RestoreCheckpoint(checkpoint)
                has_checkpoint = False
                phase = "reason"
            else:
                break

    elif phase == "reason":
        if closed_spans >= 1:
            if post_span_reasoning >= 3 and reasoning_steps >= 8:
                phase = "seek_span"
            elif helpers.ParserDistanceToComplete(generated) <= 3 and reasoning_steps >= 8:
                phase = "seek_span"
            elif helpers.MinStepsToComplete(generated) <= 4 and reasoning_steps >= 8:
                phase = "seek_span"
        else:
            if reasoning_steps >= 7 and helpers.ValidContinuationCount(generated) > 0:
                phase = "seek_span"
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        reasoning_steps = reasoning_steps + 1
        post_span_reasoning = post_span_reasoning + 1
        if helpers.EndsWithLeftDelimiter(generated):
            phase = "inside_span"
            checkpoint = helpers.Checkpoint(generated)
            has_checkpoint = True

    elif phase == "seek_span":
        if closed_spans >= 1 and post_span_reasoning >= 4 and reasoning_steps >= 9:
            final_ready = True
        elif closed_spans >= 1 and helpers.ParserDistanceToComplete(generated) <= 2 and reasoning_steps >= 8:
            final_ready = True
        elif closed_spans >= 1 and helpers.MinStepsToComplete(generated) <= 3 and reasoning_steps >= 8:
            final_ready = True
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        reasoning_steps = reasoning_steps + 1
        post_span_reasoning = post_span_reasoning + 1
